  private void PopulateAudio(){
   _out.Items.Clear();_in.Items.Clear();_out.SelectedIndex=-1;_in.SelectedIndex=-1;string backend=Convert.ToString(_driver.SelectedItem);try{if(backend=="ASIO"){foreach(var d in AsioDrivers.Enumerate()){_out.Items.Add(d);if(d.Clsid==_original.AsioDriver)_out.SelectedItem=d;}_in.Items.Add("ASIO input channels (up to 32)");_in.Enabled=false;}else if(backend.StartsWith("WASAPI")){foreach(var d in WasapiStream.Devices(false)){_out.Items.Add(d);if(d.Id==_original.OutputEndpoint)_out.SelectedItem=d;}foreach(var d in WasapiStream.Devices(true)){_in.Items.Add(d);if(d.Id==_original.InputEndpoint)_in.SelectedItem=d;}_in.Enabled=true;}else{foreach(var d in WinMmDevices.AudioOutputs()){_out.Items.Add(d);if(d.Id==_original.AudioOutput)_out.SelectedItem=d;}foreach(var d in WinMmDevices.AudioInputs()){_in.Items.Add(d);if(d.Id==_original.AudioInput)_in.SelectedItem=d;}_in.Enabled=true;}}catch(Exception ex){MessageBox.Show(this,ex.Message,"Audio devices");}if(_out.SelectedIndex<0&&_out.Items.Count>0)_out.SelectedIndex=0;if(_in.SelectedIndex<0&&_in.Items.Count>0)_in.SelectedIndex=0;Latency();
  }
  private void Latency(){if(_latency!=null&&_rate.SelectedItem!=null&&_buffer.SelectedItem!=null)_latency.Text=(Convert.ToInt32(_buffer.SelectedItem)*1000.0/Convert.ToInt32(_rate.SelectedItem)).ToString("0.00")+" ms requested/block; endpoint may impose its period";}
  private TabPage Page(TabControl t,string name){var p=new TabPage(name){BackColor=CyberTheme.Surface,ForeColor=Color.Gainsboro,Padding=new Padding(16)};t.TabPages.Add(p);return p;}
  private TableLayoutPanel Table(Control parent,int rows){var p=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=2,RowCount=rows};p.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,208));p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));for(int i=0;i<rows;i++)p.RowStyles.Add(new RowStyle(SizeType.Absolute,41));parent.Controls.Add(p);return p;}
  private void Row(TableLayoutPanel p,int row,string text,Control value){p.Controls.Add(new Label{Text=text,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleRight,Padding=new Padding(0,0,12,0)},0,row);p.Controls.Add(value,1,row);value.Margin=new Padding(5,7,5,5);}
  private NumericUpDown Number(decimal min,decimal max,decimal value){return new NumericUpDown{Minimum=min,Maximum=max,Value=value,Dock=DockStyle.Fill,BackColor=Color.FromArgb(43,43,44),ForeColor=Color.Gainsboro,BorderStyle=BorderStyle.FixedSingle};}
  private StudioChoice Choices(object[] choices,object value){var c=new StudioChoice{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};c.Items.AddRange(choices);c.SelectedItem=value;if(c.SelectedIndex<0&&c.Items.Count>0)c.SelectedIndex=0;return c;}
  private StudioChoice Devices(List<DeviceChoice> choices,int id){var c=Choices(choices.ToArray(),null);foreach(var d in choices)if(d.Id==id)c.SelectedItem=d;return c;}
  private Button Button(string text,Action action){var b=new Button{Text=text,Width=120,Height=30,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(95,95,95),ForeColor=Color.Gainsboro};b.Click+=delegate{action();};return b;}
  private List<string> ParsePaths(){var paths=new List<string>();foreach(string line in _paths.Lines){string p=line.Trim();if(p.Length>0&&!paths.Contains(p))paths.Add(p);}return paths;}
  private void Apply(){try{var s=new AppSettings{InputMode=Convert.ToString(_inputMode.SelectedItem),SmoothAnimation=_smooth.Checked,Language=_original.Language,TimelineZoom=_original.TimelineZoom,AudioBackend=Convert.ToString(_driver.SelectedItem),AudioOutput=_original.AudioOutput,AudioInput=_original.AudioInput,OutputEndpoint=_original.OutputEndpoint,InputEndpoint=_original.InputEndpoint,AsioDriver=_original.AsioDriver,PdcEnabled=_pdc.Checked,MidiInput=((DeviceChoice)_midiIn.SelectedItem).Id,MidiOutput=((DeviceChoice)_midiOut.SelectedItem).Id,SampleRate=Convert.ToInt32(_rate.SelectedItem),BufferFrames=Convert.ToInt32(_buffer.SelectedItem),UiScale=(int)_scale.Value,DefaultTempo=(double)_tempo.Value,DefaultNumerator=(int)_numerator.Value,DefaultDenominator=Convert.ToInt32(_denominator.SelectedItem),UndoLimit=(int)_undo.Value,ShortcutOverrides=new Dictionary<string,int>(_shortcutOverrides),ThemeOverrides=new Dictionary<string,int>(_themeOverrides),PluginPaths=ParsePaths(),Integration=new IntegrationSettings{ControllerEnabled=_controller.Checked,OscEnabled=_osc.Checked,OscHost=_host.Text.Trim(),OscReceivePort=(int)_oscIn.Value,OscSendPort=(int)_oscOut.Value,LinkEnabled=_link.Checked,QuickStart=_quick.Checked,RecoverySeconds=(int)_recovery.Value,ControllerBindings=(string[])_controllerBindings.Clone(),LaunchpadEnabled=_lpEnabled.Checked,LaunchpadInput=((DeviceChoice)_lpIn.SelectedItem).Id,LaunchpadOutput=((DeviceChoice)_lpOut.SelectedItem).Id,LaunchpadInputName=((DeviceChoice)_lpIn.SelectedItem).Name,LaunchpadOutputName=((DeviceChoice)_lpOut.SelectedItem).Name}};if(s.AudioBackend=="ASIO"){if(_out.SelectedItem is AsioDriverChoice)s.AsioDriver=((AsioDriverChoice)_out.SelectedItem).Clsid;else if(_original.AudioBackend!="ASIO"||String.IsNullOrEmpty(_original.AsioDriver))throw new InvalidOperationException("No 64-bit ASIO driver is installed.");}
            else if(s.AudioBackend.StartsWith("WASAPI")){if(_out.SelectedItem is AudioEndpoint)s.OutputEndpoint=((AudioEndpoint)_out.SelectedItem).Id;else if(!_original.AudioBackend.StartsWith("WASAPI"))throw new InvalidOperationException("No audio output endpoint is available.");if(_in.SelectedItem is AudioEndpoint)s.InputEndpoint=((AudioEndpoint)_in.SelectedItem).Id;}
            else{if(_out.SelectedItem is DeviceChoice)s.AudioOutput=((DeviceChoice)_out.SelectedItem).Id;else if(_original.AudioBackend!="MME")throw new InvalidOperationException("No audio output device is available.");if(_in.SelectedItem is DeviceChoice)s.AudioInput=((DeviceChoice)_in.SelectedItem).Id;}SettingsStore.Validate(s);Result=s;DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Settings",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 }
